import React, { useEffect, useRef, useState } from "react";
import TimelineScroller from "./components/TimelineScroller";
import VideoPlayer from "./components/VideoPlayer";

const formatTime = (value) => {
  const total = Math.max(0, Number(value) || 0);
  const minutes = Math.floor(total / 60);
  const seconds = Math.floor(total % 60);
  const tenths = Math.floor((total - Math.floor(total)) * 10);
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${tenths}`;
};

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

function once(element, eventName) {
  return new Promise((resolve, reject) => {
    const cleanup = () => {
      element.removeEventListener(eventName, onDone);
      element.removeEventListener("error", onError);
    };

    const onDone = () => {
      cleanup();
      resolve();
    };

    const onError = () => {
      cleanup();
      reject(new Error("Video load failed"));
    };

    element.addEventListener(eventName, onDone, { once: true });
    element.addEventListener("error", onError, { once: true });
  });
}

export default function App() {
  const fileInputRef = useRef(null);
  const videoRef = useRef(null);
  const thumbTokenRef = useRef(0);

  const [videoSrc, setVideoSrc] = useState("");
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [thumbnails, setThumbnails] = useState([]);
  const [loadingThumbnails, setLoadingThumbnails] = useState(false);
  const [uploadError, setUploadError] = useState("");

  const hasVideo = Boolean(videoSrc);

  const openFilePicker = () => fileInputRef.current?.click();

  const handleFileChange = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const url = URL.createObjectURL(file);
    setVideoSrc(url);
    setDuration(0);
    setCurrentTime(0);
    setThumbnails([]);
    setIsPlaying(false);
    setUploadError("");
    setLoadingThumbnails(true);

    const token = ++thumbTokenRef.current;

    try {
      const thumbs = await captureThumbnails(url);
      if (token === thumbTokenRef.current) {
        setThumbnails(thumbs);
      }
    } catch (error) {
      if (token === thumbTokenRef.current) {
        setUploadError("Unable to generate thumbnails for this video.");
        setThumbnails([]);
      }
    } finally {
      if (token === thumbTokenRef.current) {
        setLoadingThumbnails(false);
      }
    }

    event.target.value = "";
  };

  const handleTogglePlay = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      video.play().catch(() => {});
    } else {
      video.pause();
    }
  };

  const handleSeek = (time) => {
    const video = videoRef.current;
    if (!video || duration <= 0) return;
    const nextTime = clamp(time, 0, duration);
    video.currentTime = nextTime;
    setCurrentTime(nextTime);
  };

  return (
    <div className="min-h-screen bg-[#0f0f0f] text-slate-100">
      <div className="mx-auto grid min-h-screen max-w-6xl grid-rows-[minmax(60vh,1fr)_minmax(40vh,0.9fr)] gap-4 px-4 py-4 sm:px-6">
        <VideoPlayer
          ref={videoRef}
          src={videoSrc}
          isPlaying={isPlaying}
          currentTime={currentTime}
          onTogglePlay={handleTogglePlay}
          onTimeUpdate={setCurrentTime}
          onDurationChange={setDuration}
          onPlay={() => setIsPlaying(true)}
          onPause={() => setIsPlaying(false)}
          hasVideo={hasVideo}
        />

        <TimelineScroller
          duration={duration}
          currentTime={currentTime}
          thumbnails={thumbnails}
          loading={loadingThumbnails}
          onSeek={handleSeek}
          onUploadClick={openFilePicker}
        />
      </div>

      <input type="file" accept="video/*" ref={fileInputRef} className="hidden" onChange={handleFileChange} />

      {uploadError && (
        <div className="mx-auto mt-4 max-w-6xl rounded-[22px] bg-[#1f2937]/80 px-4 py-3 text-sm text-pink-200 ring-1 ring-pink-500/20">
          {uploadError}
        </div>
      )}
    </div>
  );
}

async function captureThumbnails(src) {
  const video = document.createElement("video");
  video.src = src;
  video.crossOrigin = "anonymous";
  video.muted = true;
  video.playsInline = true;
  video.preload = "auto";

  await once(video, "loadedmetadata");
  const duration = Number(video.duration) || 0;
  if (!duration || !isFinite(duration)) {
    throw new Error("Invalid video duration");
  }

  const canvas = document.createElement("canvas");
  const targetWidth = 160;
  const aspect = video.videoWidth && video.videoHeight ? video.videoWidth / video.videoHeight : 16 / 9;
  canvas.width = targetWidth;
  canvas.height = Math.round(targetWidth / aspect);

  const ctx = canvas.getContext("2d");
  const frames = [];
  const totalSeconds = Math.floor(duration);

  for (let second = 0; second <= totalSeconds; second += 1) {
    video.currentTime = Math.min(second, duration);
    await once(video, "seeked");
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    frames.push({
      id: second,
      time: Number(second.toFixed(1)),
      src: canvas.toDataURL("image/jpeg", 0.72),
    });
  }

  video.src = "";
  return frames;
}
